-- ===== 車販注文書の新規作成の権限(LoginManagement.CheckCanUseFuncWithMessage は メニュー設定.表示名称 で引く)。新規見積書・新規注文書・コピーして新規作成(No51〜No53)で開くのに要る =====
IF NOT EXISTS (SELECT 1 FROM [dbo].[メニュー設定] WHERE [表示名称] = N'車販見積書新規作成') BEGIN SET IDENTITY_INSERT [dbo].[メニュー設定] ON; INSERT [dbo].[メニュー設定] ([ID], [アプリ名], [メニュー区分], [サブ番号], [表示名称], [業務案内], [引数構成], [起動区分], [属性], [編集禁止フラグ], [新機能フラグ]) SELECT ISNULL(MAX([ID]), 0) + 1, N'車販注文書', 0, 0, N'車販見積書新規作成', N'', N'', 0, 0, 0, 0 FROM [dbo].[メニュー設定]; SET IDENTITY_INSERT [dbo].[メニュー設定] OFF; END
IF NOT EXISTS (SELECT 1 FROM [dbo].[メニュー設定] WHERE [表示名称] = N'車販注文書新規作成') BEGIN SET IDENTITY_INSERT [dbo].[メニュー設定] ON; INSERT [dbo].[メニュー設定] ([ID], [アプリ名], [メニュー区分], [サブ番号], [表示名称], [業務案内], [引数構成], [起動区分], [属性], [編集禁止フラグ], [新機能フラグ]) SELECT ISNULL(MAX([ID]), 0) + 1, N'車販注文書', 0, 0, N'車販注文書新規作成', N'', N'', 0, 0, 0, 0 FROM [dbo].[メニュー設定]; SET IDENTITY_INSERT [dbo].[メニュー設定] OFF; END

